#!/usr/bin/env python3
"""Randomised cross-check of the campaign submission against tools/reference.py."""
import base64, hashlib, ipaddress, json, plistlib, random, struct, sys, io, csv as csvmod

sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/deps')
sys.path.insert(0, '/workspace/tools')

DOC = ipaddress.IPv6Network('2001:db8::/32')
HEADER = ('type,id,revision,published,op,lease,event,probe,target,responder,result,'
          'service,attempt,payload')


def ident(rng, prefix, index):
    return '%s%d' % (prefix, index)


def aligned(rng, bits):
    base = int(DOC.network_address)
    step = 1 << (128 - bits)
    span = (1 << 128) - base
    return base + step * rng.randrange(1, span // step)


def txt(value):
    return str(ipaddress.IPv6Address(value))


def other(rng, value):
    delta = rng.choice([1, 2, 3, 7, -1, -2, 255])
    return (value + delta) & ((1 << 128) - 1)


def make_adb(rng, corrupt=None):
    kind = rng.choice(['CNXN', 'CNXN', 'AUTH', 'CLSE'])
    command = {'CNXN': 0x4e584e43, 'AUTH': 0x48545541, 'CLSE': 0x45534c43}[kind]
    arg0 = rng.choice([0x01000000, 0x01000002, rng.randrange(1 << 32)])
    arg1 = rng.choice([0, 4096])
    if command == 0x4e584e43:
        body = rng.choice([b'host::zgrab2', 'héllo'.encode(), b'', b'adb@%s' % b'x' * 3])
    else:
        body = bytes(rng.randrange(256) for _ in range(rng.randrange(0, 6)))
    length, check, magic = len(body), sum(body) & 0xffffffff, command ^ 0xffffffff
    if corrupt == 'checksum':
        check ^= 1
    elif corrupt == 'magic':
        magic ^= 1
    elif corrupt == 'length':
        length += 1
    elif corrupt == 'extra':
        body += b'zz'
    elif corrupt == 'trunc':
        return struct.pack('<6I', command, arg0, arg1, len(body), check, magic) + body[:1]
    return struct.pack('<6I', command, arg0, arg1, length, check, magic) + body


def make_sync(rng, corrupt=None, order=('ProductVersion', 'ProductName'), fmt=None):
    fmt = fmt or rng.choice([plistlib.FMT_XML, plistlib.FMT_BINARY])
    blob = b''
    for index, key in enumerate(order):
        obj = {'Key': key, 'Request': 'GetValue',
               'Value': rng.choice(['17.1', 'iPhone12,3', 'x' * 2])}
        if corrupt == 'keys' and index == 0:
            obj = {'Key': key, 'Request': 'GetValue', 'Value': 'a', 'Label': 'b'}
        if corrupt == 'empty' and index == 0:
            obj['Value'] = ''
        if corrupt == 'wrong' and index == 0:
            obj['Key'] = 'Nope'
        if corrupt == 'req' and index == 0:
            obj['Request'] = 'ListDevices'
        body = plistlib.dumps(obj, fmt=fmt)
        if corrupt == 'len' and index == 0:
            blob += struct.pack('>I', len(body) + 3) + body
            continue
        blob += struct.pack('>I', len(body)) + body
    if corrupt == 'trailing':
        blob += b'\x00\x00\x00\x01'
    if corrupt == 'junk':
        blob = b'not-a-plist-at-all'
    return blob


class Campaign:
    def __init__(self, rng):
        self.rng = rng
        self.rows = []
        self.counter = 0

    def name(self, prefix='r'):
        self.counter += 1
        return ident(self.rng, prefix, self.counter)

    def build(self):
        rng = self.rng
        seed = self.name('seed')
        services = []
        for index, kind in enumerate(rng.sample(['tcp', 'adb', 'sync'], rng.randrange(0, 4))):
            services.append({'id': ident(rng, 'S', index), 'kind': kind})
        queries = sorted(rng.sample(range(0, 900), rng.randrange(1, 4)))
        leases = []
        chosen = []
        for index in range(rng.randrange(0, 4)):
            bits = 56 if rng.random() < .6 else 64
            if chosen and rng.random() < .35:
                bits, base = chosen[-1]
            else:
                base = aligned(rng, bits)
                chosen.append((bits, base))
            subnets = sorted(rng.sample(range(256), rng.randrange(1, 4))) if bits == 56 else [0]
            leases.append({'id': ident(rng, 'L', index),
                           'prefix': str(ipaddress.IPv6Network((base, bits))),
                           'start': rng.randrange(0, 20),
                           'end': rng.choice([rng.randrange(30, 200), 10 ** 12 + 1,
                                             rng.randrange(900, 5000)]),
                           'subnets': subnets, 'low_count': rng.randrange(1, 4)})
        self.leases, self.services, self.queries, self.seed = leases, services, queries, seed
        self.probes = {}
        self.lows = {}
        for lease in leases:
            net = ipaddress.IPv6Network(lease['prefix'], strict=True)
            base = int(net.network_address)
            table = {}
            lows = set()
            for subnet in sorted(lease['subnets']):
                n64 = base + (subnet << 64)
                canonical = str(ipaddress.IPv6Network((n64, 64)))
                digest = hashlib.sha256('\n'.join([seed, lease['id'], canonical]).encode()).digest()
                canary = int.from_bytes(digest[:8], 'big') | (1 << 63)
                table['%d/c' % subnet] = (n64 + canary, True)
                for i in range(1, lease['low_count'] + 1):
                    table['%d/i%d' % (subnet, i)] = (n64 + i, False)
                    lows.add(n64 + i)
            self.probes[lease['id']] = table
            self.lows[lease['id']] = lows
        self.evidence = {}      # lease -> {'internal': set, 'external': set}
        self.make_rows()
        captures = self.captures()
        requests, quotas_r = self.make_requests()
        offers, quotas_o = self.make_offers(requests)
        return {'version': 3, 'seed': seed, 'leases': leases, 'services': services,
                'queries': queries, 'captures': captures, 'requests': requests,
                'offers': offers, 'request_quotas': quotas_r, 'offer_quotas': quotas_o}

    # -- records -----------------------------------------------------------
    def put_icmp(self, lease, probe, values=None, **kw):
        rng = self.rng
        target, canary = self.probes[lease][probe]
        result = kw.get('result') or rng.choice(['echo', 'echo', 'echo', 'error', 'timeout'])
        if result == 'timeout':
            responder = ''
        elif result == 'echo':
            responder = target if (canary or rng.random() < .7) else other(rng, target)
        else:
            responder = target if rng.random() < .4 else other(rng, target)
        row = self.leases_lookup[lease]
        event = kw.get('event', rng.randrange(row['start'], min(row['end'], 900)))
        published = kw.get('published', rng.choice(self.queries + [rng.randrange(0, 900)]))
        values = values or [target, responder]
        self.rows.append(['icmp', kw.get('name') or self.name(), kw.get('revision', 0),
                          published, 'put', lease, event, probe,
                          txt(values[0]) if not isinstance(values[0], str) else values[0],
                          txt(values[1]) if isinstance(values[1], int) else values[1],
                          result, '', '', ''])
        if not canary and result != 'timeout':
            bucket = self.evidence.setdefault(lease, {'internal': set(), 'external': set()})
            if result == 'echo' and (values[1] == target or txt(values[1]) == txt(target)):
                bucket['internal'].add(target)
            else:
                bucket['external'].add(values[1] if isinstance(values[1], int)
                                       else int(ipaddress.IPv6Address(values[1])))

    def put_app(self, lease, target, service, attempt, result, payload=b'', **kw):
        rng = self.rng
        row = self.leases_lookup[lease]
        event = kw.get('event', rng.randrange(row['start'], min(row['end'], 900)))
        published = kw.get('published', rng.choice(self.queries))
        self.rows.append(['app', kw.get('name') or self.name('a'), kw.get('revision', 0),
                          published, 'put', lease, event, '', txt(target), '', result,
                          service, attempt,
                          base64.b64encode(payload).decode() if payload else ''])

    def delete(self, kind, name, **kw):
        self.rows.append([kind, name, kw.get('revision', 1),
                          kw.get('published', self.rng.choice(self.queries)), 'delete']
                         + [''] * 9)

    def make_rows(self):
        rng = self.rng
        self.leases_lookup = {l['id']: l for l in self.leases}
        if not self.leases:
            return
        for lease in self.leases:
            probes = sorted(self.probes[lease['id']])
            for probe in probes:
                if rng.random() < .85:
                    self.put_icmp(lease['id'], probe)
            # revisions, duplicates, conflicts and tombstones
            for _ in range(rng.randrange(0, 4)):
                if not probes:
                    break
                name = self.name()
                for revision in range(rng.randrange(1, 3)):
                    self.put_icmp(lease['id'], rng.choice(probes), name=name,
                                  revision=revision, published=rng.choice(self.queries))
            if rng.random() < .3 and probes:
                # two distinct contents at the same revision => conflict
                name = self.name()
                self.put_icmp(lease['id'], probes[0], name=name, revision=2,
                              result='echo', published=max(self.queries))
                self.rows[-1][7] = probes[-1]
                self.rows[-1][8] = txt(self.probes[lease['id']][probes[-1]][0])
            if rng.random() < .3:
                name = self.name()
                self.put_icmp(lease['id'], rng.choice(probes), name=name, revision=1,
                              published=rng.choice(self.queries))
                if rng.random() < .7:
                    self.delete('icmp', name, revision=2)
                else:
                    self.delete('icmp', name, revision=0)
        for _ in range(rng.randrange(0, 8)):
            lease = rng.choice(self.leases)['id']
            evidence = self.evidence.get(lease, {'internal': set(), 'external': set()})
            pool = sorted(evidence['internal'] | evidence['external'] | self.lows[lease])
            if not pool or not self.services:
                continue
            service = rng.choice(self.services)
            target = rng.choice(pool)
            attempts = sorted(rng.sample(range(0, 5), rng.randrange(1, 3)))
            for attempt in attempts:
                if service['kind'] == 'tcp':
                    payload, result = b'', rng.choice(['open', 'closed', 'timeout'])
                else:
                    result = rng.choice(['open', 'open', 'open', 'closed', 'timeout'])
                    if result == 'open':
                        payload = (make_adb(rng, rng.choice([None, None, 'checksum', 'magic',
                                                             'length', 'extra', 'trunc']))
                                   if service['kind'] == 'adb'
                                   else make_sync(rng, rng.choice([None, None, None, 'keys',
                                                                   'empty', 'wrong', 'trailing',
                                                                   'junk', 'len', 'req'])))
                    else:
                        payload = b''
                self.put_app(lease, target, service['id'], attempt, result, payload)
        # deliberately malformed records
        for _ in range(rng.randrange(0, 6)):
            self.rows.append(self.bad_row())

    def bad_row(self):
        rng = self.rng
        lease = rng.choice(self.leases)
        choice = rng.randrange(0, 10)
        name = self.name('bad')
        base = ['icmp', name, 0, 500, 'put', lease['id'], 10, '0/i1',
                txt(self.lows[lease['id']][0] if self.lows[lease['id']] else 0),
                '', 'echo', '', '', '']
        if choice == 0:
            return base[:13]
        if choice == 1:
            row = list(base); row[6] = lease['end'] + 5; return row
        if choice == 2:
            row = list(base); row[7] = '9/i99'; return row
        if choice == 3:
            row = list(base); row[8] = txt(other(rng, int(ipaddress.IPv6Address(row[8])))); return row
        if choice == 4:
            row = list(base); row[10] = 'refused'; return row
        if choice == 5:
            row = list(base); row[11] = 'x'; return row
        if choice == 6:
            row = ['app', name, 0, 500, 'put', lease['id'], 10, '', 'ff02::1', '', 'open',
                   self.services[0]['id'] if self.services else 'nope', 0, '']; return row
        if choice == 7:
            row = ['app', name, 0, 500, 'put', lease['id'], 10, '', txt(next(iter(self.lows[lease['id']]), 0)),
                   '', 'closed', self.services[0]['id'] if self.services else 'x', 0, '!!!']; return row
        if choice == 8:
            return ['icmp', name, 0, 500, 'purge', lease['id'], 10, '0/i1',
                    txt(next(iter(self.lows[lease['id']]), 0)), '', 'echo', '', '', '']
        return [''] * 14

    def captures(self):
        rng = self.rng
        rows = list(self.rows)
        rng.shuffle(rows)
        out = [HEADER]
        for values in rows:
            out.append(','.join(str(v) for v in values))
        blob = ('\r\n'.join(out) + '\r\n').encode()
        return [{'encoding': 'csv', 'chunks': [base64.b64encode(blob).decode()]}]


def reference_pipeline(job):
    import campaign as C
    from common import validate, CaptureError, Invalid
    import reference as R
    context = validate(job)
    manifest, probes, low = C_plan(context)
    rows, rejected, error = R.decode_captures(job, probes)
    if error:
        return {'error': error}
    snapshots = R.census(job, rows, probes, low)
    active = R.activity(job, snapshots)
    pairs = R.allowed(job, None, active)
    return {'manifest': manifest, 'rejected': rejected, 'snapshots': snapshots,
            'active_requests': [{'id': k, 'active': v} for k, v in sorted(active.items())],
            'opt': R.optimum(job, active, pairs), 'pairs': pairs, 'rows': rows}


def C_plan(context):
    from gen_targets import plan
    return plan(context['leases'], context['seed'])


def main():
    import campaign
    count = int(sys.argv[1]) if len(sys.argv) > 1 else 25
    start = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    for case in range(start, start + count):
        rng = random.Random(case)
        job = Campaign(rng).build()
        try:
            got = campaign.audit(json.loads(json.dumps(job)))
        except Exception as exc:
            print('case', case, 'submission raised', type(exc).__name__, exc)
            import traceback; traceback.print_exc()
            return 1
        want = reference_pipeline(job)
        if want.get('manifest') != got['manifest']:
            print('case', case, 'manifest mismatch')
            return 1
        if want['rejected'] != got['rejected']:
            print('case', case, 'rejected mismatch')
            print(' want', want['rejected'][:5])
            print(' got ', got['rejected'][:5])
            return 1
        if want['snapshots'] != got['snapshots']:
            print('case', case, 'snapshot mismatch')
            for a, b in zip(want['snapshots'], got['snapshots']):
                if a != b:
                    for key in a:
                        if a[key] != b[key]:
                            print('  query', a['at'], 'key', key)
                            if key == 'leases':
                                for x, y in zip(a[key], b[key]):
                                    if x != y:
                                        for kk in x:
                                            if x[kk] != y[kk]:
                                                print('    lease', x['lease'], kk, x[kk], y[kk])
                                        break
                            else:
                                print('   ', a[key], b[key])
                    break
            return 1
        if want['active_requests'] != got['active_requests']:
            print('case', case, 'activity mismatch', want['active_requests'], got['active_requests'])
            return 1
        opt = want['opt']
        if opt is not None:
            key, chosen = opt
            if -key[0] != got['plan']['resolved'] or key[1] != got['plan']['cost']:
                print('case', case, 'plan mismatch: brute', key, 'flow',
                      got['plan']['resolved'], got['plan']['cost'])
                return 1
        print('case', case, 'ok', 'rows', len(want['rows']), 'resolved',
              got['plan']['resolved'], 'cost', got['plan']['cost'])
    return 0


if __name__ == '__main__':
    sys.exit(main())
